  "evidence_points": [
    "表面存在非对称、随机分布的凹陷与隆起，符合物理膨胀/收缩形成的自然形变",
    "局部有细微纤维状结构与微小杂质颗粒（如左上角黑点），符合真实食材拍摄特征",
    "光照方向一致，阴影柔和且符合曲面漫反射特性，无AI合成中常见的异常高光或阴影断裂"
  ]
}

